import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"系统与安装要求","description":"确认 v1.0 已测试系统、安装包、服务器权限、磁盘余量和访问条件。","frontmatter":{"title":"系统与安装要求","description":"确认 v1.0 已测试系统、安装包、服务器权限、磁盘余量和访问条件。","status":"reviewed","kind":"reference"},"headers":[],"relativePath":"zh/reference/system-requirements.md","filePath":"zh/参考资料/系统与安装要求.md"}'),o={name:"zh/reference/system-requirements.md"};function i(n,t,l,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="系统与安装要求" tabindex="-1">系统与安装要求 <a class="header-anchor" href="#系统与安装要求" aria-label="Permalink to &quot;系统与安装要求&quot;">​</a></h1><p>本页用于准备 <strong>InduFrame v1.0 平台中心</strong>。如果只是登录已安装的平台，向组织管理员取得访问地址和账号即可，不需要自己安装服务器。</p><h2 id="优先推荐-ubuntu-24" tabindex="-1">优先推荐 Ubuntu 24 <a class="header-anchor" href="#优先推荐-ubuntu-24" aria-label="Permalink to &quot;优先推荐 Ubuntu 24&quot;">​</a></h2><p><strong>目前只测试了 Ubuntu 24，优先推荐这个系统。其他系统尚未测试，不作为已验证支持范围推荐。</strong></p><p>安装脚本包含 Linux 环境检查，不表示所有 Linux 发行版都已经测试通过。不要把 Ubuntu 24 的安装、卸载结论直接用于其他系统；本页流程也不用于在 Windows 上安装平台中心。</p><h2 id="安装前需要具备什么" tabindex="-1">安装前需要具备什么 <a class="header-anchor" href="#安装前需要具备什么" aria-label="Permalink to &quot;安装前需要具备什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>安装包</td><td>交付人员提供的完整包，版本和服务器架构匹配</td></tr><tr><td>系统账号</td><td>具备系统管理权限，能够使用 <code>sudo</code></td></tr><tr><td>系统服务</td><td>服务器使用 systemd 管理服务，由维护人员确认</td></tr><tr><td>操作方式</td><td>在能输入回答的终端中运行安装或卸载程序</td></tr><tr><td>系统盘余量</td><td>至少 30 GiB，且至少保留磁盘总容量的 20%</td></tr><tr><td>独立数据盘余量</td><td>另外使用数据盘时，该盘也同时满足上述两项余量</td></tr><tr><td>网络</td><td>使用者能访问公共入口，平台管理员能访问管理入口所在网络</td></tr></tbody></table><p>CPU、内存和业务存储容量应按工程规模、历史数据量和使用人数评估。本页不把磁盘最低余量作为实际业务容量承诺。</p><h2 id="安装位置与数据盘" tabindex="-1">安装位置与数据盘 <a class="header-anchor" href="#安装位置与数据盘" aria-label="Permalink to &quot;安装位置与数据盘&quot;">​</a></h2><p>向导默认填写程序父目录 <code>/opt</code>，实际程序目录为 <code>/opt/induframe</code>。选择其他程序存放位置，不会自动把运行数据迁移到那个磁盘。</p><p>如果需要专门安排数据盘，先与服务器维护人员确认磁盘及数据位置，再安装。不要以手工移动平台目录或删除原数据来调整存放位置。</p><h2 id="地址、端口和证书" tabindex="-1">地址、端口和证书 <a class="header-anchor" href="#地址、端口和证书" aria-label="Permalink to &quot;地址、端口和证书&quot;">​</a></h2><ul><li>公共入口使用 HTTPS，默认端口 <code>443</code>；组织成员从这里登录。</li><li>管理入口使用安装结果给出的内网 HTTP 地址，默认端口 <code>18100</code>，路径带 <code>/admin/</code>。</li><li>两个端口不能相同，也不能与服务器上其他服务冲突。</li><li>默认证书方式为 <code>self-signed</code>。使用者遇到信任提醒时，应由维护人员核对地址和证书后处理。</li><li>使用已有证书的 <code>provided</code> 方式，需要维护人员预先核对文件、私钥及适用地址，不直接套用默认证书的验证结论。</li></ul><p>完整离线包仍可能要求服务器事先具备必要的系统网络组件。完全离线时，请维护人员提前准备。客户服务器不需要另外安装 Docker，平台安装器会准备自身需要的运行环境。</p><h2 id="相关操作" tabindex="-1">相关操作 <a class="header-anchor" href="#相关操作" aria-label="Permalink to &quot;相关操作&quot;">​</a></h2><p><a href="/induframe-docs/zh/installation/prepare.html">准备安装材料</a> · <a href="/induframe-docs/zh/installation/install.html">开始安装</a> · <a href="/induframe-docs/zh/reference/install-options.html">查询向导字段</a> · <a href="/induframe-docs/zh/releases/">查看版本记录</a></p>',16)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
